import sys
from typing import List

def max_monsters_defeated(N: int, A: List[int], B: List[int]) -> int:
    total = 0
    for i in range(N):
        if A[i] <= B[i]:
            total += A[i]
        else:
            total += B[i]
        if i < N - 1 and A[i + 1] <= B[i]:
            continue
        elif i < N - 1:
            total += min(A[i + 1], B[i])
    return total

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:N + 2]))
    B = list(map(int, data[N + 2:]))
    print(max_monsters_defeated(N, A, B))
